use std::sync::Mutex;
use once_cell::sync::Lazy;

/// Global configuration for array printing
static PRINT_OPTIONS: Lazy<Mutex<PrintOptions>> =
    Lazy::new(|| Mutex::new(PrintOptions::default()));

/// Public API: configure print options. Any `None` leaves the current setting unchanged.
fn set_printoptions(
    precision: Option<u8>,
    threshold: Option<u8>,
    edgeitems: Option<u8>,
    linewidth: Option<u8>,
    suppress: Option<bool>,
    nanstr: Option<String>,
    infstr: Option<String>,
    sign: Option<String>,
    floatmode: Option<String>,
    legacy: Option<String>,
) {
    let mut cfg = PRINT_OPTIONS.lock().unwrap();

    if let Some(p) = precision {
        assert!(p > 0, "Precision must be strictly positive");
        cfg.precision = p;
    }

    if let Some(t) = threshold {
        assert!(t > 0, "Threshold must be strictly positive");
        cfg.threshold = t;
    }

    if let Some(e) = edgeitems {
        assert!(e > 0, "Edge-items must be strictly positive");
        cfg.edgeitems = e;
    }

    if let Some(lw) = linewidth {
        assert!(lw > 0, "Line width must be strictly positive");
        cfg.linewidth = lw;
    }

    if let Some(s) = suppress {
        cfg.suppress = s;
    }

    if let Some(ns) = nanstr {
        assert!(!ns.is_empty(), "NaN string must be non-empty");
        cfg.nanstr = ns;
    }

    if let Some(is_) = infstr {
        assert!(!is_.is_empty(), "Infinity string must be non-empty");
        cfg.infstr = is_;
    }

    if let Some(sign_str) = sign {
        cfg.sign = match sign_str.as_str() {
            "-" => Sign::Minus,
            "+" => Sign::Plus,
            " " => Sign::Space,
            _ => panic!("Sign must be one of \"-\", \"+\", or \" \""),
        };
    }

    if let Some(mode) = floatmode {
        cfg.floatmode = match mode.as_str() {
            "fixed" => FloatMode::Fixed,
            "unique" => FloatMode::Unique,
            "maxprec" => FloatMode::MaxPrec,
            "maxprec_equal" => FloatMode::MaxPrecEqual,
            _ => panic!("Float mode must be one of \"fixed\", \"unique\", \"maxprec\", or \"maxprec_equal\""),
        };
    }

    if let Some(mode) = legacy {
        cfg.legacy = match mode.as_str() {
            "1.13" => LegacyMode::V1_13,
            "1.21" => LegacyMode::V1_21,
            "1.25" => LegacyMode::V1_25,
            "2.1" => LegacyMode::V2_1,
            "2.2" => LegacyMode::V2_2,
            _ => panic!("Legacy mode must be one of \"1.13\", \"1.21\", \"1.25\", \"2.1\", or \"2.2\""),
        };
    }
}

